CREATE OR REPLACE FUNCTION public.pms_confirm_payment(_payment uuid, _reference text DEFAULT NULL::text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare _org uuid:=public.current_org_id(); p public.payments; f public.folios; alloc_exists boolean; begin if _org is null then return jsonb_build_object('ok',false,'reason','no_organisation'); end if; if not (public.has_permission('pms','payments.confirm') or public.has_permission('finance','approve') or public.is_org_admin() or public.neo_system_posting()) then raise exception 'Not permitted to confirm payments' using errcode='42501'; end if; select * into p from public.payments where id=_payment and organization_id=_org for update; if p.id is null then return jsonb_build_object('ok',false,'reason','not_found'); end if; if p.status='confirmed' then return jsonb_build_object('ok',true,'reason','already_confirmed','payment_id',p.id); end if; if p.status not in ('pending','processing','submitted') then return jsonb_build_object('ok',false,'reason','invalid_status','status',p.status); end if; if p.method not in ('cash','corporate-credit') and coalesce(nullif(trim(coalesce(_reference,p.external_reference,'')),''),'')='' then return jsonb_build_object('ok',false,'reason','reference_required','detail','External payments require a confirmation reference.'); end if; select * into f from public.folios where id=p.folio_id and organization_id=_org for update; if f.id is null then return jsonb_build_object('ok',false,'reason','folio_not_found'); end if; if f.status not in ('open','under-review') then return jsonb_build_object('ok',false,'reason','folio_not_open','status',f.status); end if; select exists(select 1 from public.payment_allocations a where a.payment_id=p.id and a.folio_id=f.id) into alloc_exists; if not alloc_exists then insert into public.payment_allocations(organization_id,payment_id,folio_id,amount,created_by) values(_org,p.id,f.id,p.amount,auth.uid()); update public.folios set total_payments=total_payments+p.amount,balance=balance-p.amount,updated_at=now() where id=f.id; end if; update public.payments set status='confirmed',external_reference=coalesce(nullif(trim(_reference),''),external_reference),notes=concat_ws(' · ',nullif(notes,''),nullif(_note,'')),paid_at=now(),updated_at=now() where id=p.id; insert into public.audit_logs(organization_id,user_id,user_name,action,module,record_id,new_value,reason) values(_org,auth.uid(),'','pms.payment.confirm','finance',p.id::text,jsonb_build_object('folio_id',f.id,'amount',p.amount,'method',p.method,'reference',coalesce(nullif(trim(_reference),''),p.external_reference)),_note); return jsonb_build_object('ok',true,'payment_id',p.id,'folio_id',f.id,'amount',p.amount,'balance',(select balance from public.folios where id=f.id)); end $function$;
